declare const a: unique symbol, b: unique symbol;
type A = Token<typeof a, number>; type BadA = Token<typeof a, string>; type B = Token<typeof b, number>;
type BindA = Provider<() => number, {}, readonly [], TokenGraph<readonly [], A>>;
type BindWrongA = Provider<() => string, {}, readonly [], TokenGraph<readonly [], BadA>>;
type BindB = Provider<() => number, {}, readonly [], TokenGraph<readonly [], B>>;
type NeedA = Provider<() => number, {}, readonly [], TokenGraph<readonly [A]>>;
type NeedWrongA = Provider<() => number, {}, readonly [], TokenGraph<readonly [BadA]>>;
type OpaqueTokens = Provider<() => number, {}, readonly [], TokenGraph<readonly [TokenBase]>>;
type Opaque = ProviderBase;
type Named = (deps: {x: number}) => number;
type SymbolNamed = (deps: {[a]: number}) => number;
type AnyNamed = (deps: any) => number;
type NeverNamed = (deps: never) => number;
type UnionNamed = (deps: {x: number} | {y: string}) => number;
type OptionalNamed = (deps: {x?: number}) => number;

type OptionalA = Provider<() => number, {}, readonly [], TokenGraph<readonly [], never, readonly [A]>>;
type AnyTokenNeed = Provider<() => number, {}, readonly [], TokenGraph<readonly [any]>>;
type NeverGraph = Provider<() => number, {}, readonly [], never>;
type NeedB = Provider<() => number, {}, readonly [], TokenGraph<readonly [B]>>;
